qasm_string = """OPENQASM 3.0;
include "stdgates.inc";
qubit[8] q;
ry(2.0943951023931953) q[0];
cx q[0], q[1];
ry(1.9106332362490186) q[1];
cx q[1], q[2];
ry(1.8234765819369754) q[2];
cx q[2], q[3];
ry(1.7721542475852274) q[3];
cx q[3], q[4];
ry(1.7382444060145859) q[4];
cx q[4], q[5];
ry(1.7141438957002622) q[5];
cx q[5], q[6];
ry(1.696124157962962) q[6];
cx q[6], q[7];
x q[0];
x q[1];
x q[2];
x q[3];
x q[4];
x q[5];
x q[6];
cx q[7], q[6];
ccx q[6], q[7], q[5];
ccx q[5], q[6], q[4];
ccx q[4], q[5], q[3];
ccx q[3], q[4], q[2];
ccx q[2], q[3], q[1];
ccx q[1], q[2], q[0];
x q[1];
x q[2];
x q[3];
x q[4];
x q[5];
x q[6];
x q[7];
"""

code_string = """from qiskit import transpile

def run_and_analyze(circuit, aer_sim):
    compiled = transpile(circuit, aer_sim)
    result = aer_sim.run(compiled, shots=1, memory=True).result()
    bitstr = result.get_memory(compiled)[0]  # e.g., '01000000' for 8 qubits
    # Qiskit memory string is ordered from highest classical bit to lowest.
    # If measurement was added by the verifier in the same order q[i] -> c[i],
    # then bitstr[::-1][i] corresponds to qubit i.
    bitstr_q = bitstr[::-1]
    return [i for i, b in enumerate(bitstr_q) if b == '1']
"""
END_FILE>>>

